        var create=runs.request(json.canonical(runDecision.required("request")).getBytes(StandardCharsets.UTF_8));same(decision.resultingTaskRevision(),create.task_revision());same(decision.resultingPlanRevision(),create.plan_revision());same(str(revision,"snapshot_id"),create.snapshot_id());same(str(run,"budget_revision"),create.budget_revision());for(String f:List.of("task_revision","plan_revision","snapshot_id","budget_revision")){same(runDecision.required("request").required(f),replay.required(f));same(runDecision.required("request").required(f),saved.required(f));}same(text(saved,"agent_release_id"),text(replay,"agent_release_id"));
