    /** Mutable observational status is deliberately outside the immutable answer
     * receipt. A truthful answer and STALE old baseline do not depend on start I/O. */
    JsonNode continuation(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,JsonNode request)throws Exception {
        require(q,request);var target=request.required("target_run");
        var values=new HashMap<String,Object>();values.put("projectId",q.projectId());values.put("taskId",q.taskId());
        values.put("runId",text(target,"run_id"));values.put("commandId",text(target,"command_id"));
        var saved=runs.read(one(runRows.created(values)));var observed=launches.questionLaunch(q,saved);
        var started=starts.questionStart(q,observed,saved);
        var result=continuationStatus(json,text(target,"run_id"),observed.acceptance()==null?null:observed.acceptance().content(),started);
        q.requireUnchanged();return result;
    }
    static JsonNode continuationStatus(PermissionSchema json,String run,JsonNode acceptance,JsonNode started)throws Exception {
        if(started!=null&&acceptance==null)bad();
        if(acceptance!=null)same(run,text(acceptance,"run_id"));
        if(started!=null){same(run,text(started,"run_id"));same(text(acceptance,"temporal_run_id"),text(started,"temporal_run_id"));same(hash(acceptance),text(started,"workflow_acceptance_sha256"));}
        var result=json.object().put("target_run_id",run).put("status",started!=null?"STARTED":acceptance!=null?"WORKFLOW_ACCEPTED":"CREATED_NOT_STARTED")
                .put("can_resume_frozen_run",false).put("is_current_run_status",false);
        result.set("workflow_acceptance",acceptance==null?json.tree(null):acceptance.deepCopy());
        result.set("accepted_start",started==null?json.tree(null):started.deepCopy());return result;
    }
    static void requireChanged(JsonNode cause,JsonNode oldReplay,JsonNode replay){
        if(oldReplay.required("task_revision").equals(replay.required("task_revision"))||oldReplay.required("plan_revision").equals(replay.required("plan_revision")))deny();
        String type=text(cause.required("request").required("arguments"),"question_type");
        if("NEED_EVIDENCE".equals(type)){if(oldReplay.required("scope_snapshot").required("members").equals(replay.required("scope_snapshot").required("members")))deny();}
        else if("CLARIFY_APPLICABILITY".equals(type)){if(oldReplay.required("plan").required("content").equals(replay.required("plan").required("content"))&&oldReplay.required("project_profile").required("content_sha256").equals(replay.required("project_profile").required("content_sha256")))deny();}else deny();
        String section=text(cause.required("node_input"),"section_id");boolean found=false;for(var s:replay.required("plan").required("content").required("sections"))if(section.equals(text(s,"section_id")))found=true;if(!found)deny();
    }
    private JsonNode plan(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String id)throws Exception{
        var row=one(db.queryForList("SELECT p.*,c.content_json,c.schema_ref,c.schema_version,c.schema_manifest_sha256 FROM plan_revision p JOIN plan_content_revision c ON c.tenant_id=p.tenant_id AND c.project_id=p.project_id AND c.task_id=p.task_id AND c.task_revision=p.task_revision AND c.plan_revision=p.plan_revision AND c.content_sha256=p.content_sha256 WHERE p.tenant_id=? AND p.project_id=? AND p.task_id=? AND p.plan_revision=? LIMIT 2 FOR UPDATE",q.tenantId(),q.projectId(),q.taskId(),id));var content=inputs.read(str(row,"content_json"));var typed=TypedSchemaBindings.bind(catalogue,ArtifactBindings.PLAN_CANDIDATE,content);same(typed.payload().schemaRef(),str(row,"schema_ref"));same(inputs.manifestSha256(),str(row,"schema_manifest_sha256"));same("1.0.0",str(row,"schema_version"));same(hash(content),str(row,"content_sha256"));version(q,id,"PLAN_REVISION",hash(content));var result=json.object().put("task_revision",str(row,"task_revision"));result.set("decision_id",json.tree(row.get("decision_id")));result.set("content",content);return result;
    }
    private Map<String,Object> taskRevision(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String id){var row=one(db.queryForList("SELECT * FROM task_revision WHERE tenant_id=? AND project_id=? AND task_id=? AND task_revision=? LIMIT 2 FOR UPDATE",q.tenantId(),q.projectId(),q.taskId(),id));version(q,id,"TASK_REVISION",str(row,"content_sha256"));return row;}
    private void version(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String id,String kind,String sha){one(db.queryForList("SELECT version_id FROM version_registry WHERE tenant_id=? AND owner_project_id=? AND version_id=? AND entity_kind=? AND content_sha256=? LIMIT 2 FOR UPDATE",q.tenantId(),q.projectId(),id,kind,sha));}
    private void lineage(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String from,String original){var seen=new HashSet<String>();String at=from;for(int n=0;n<1024;n++){if(at.equals(original))return;if(!seen.add(at))bad();var row=taskRevision(q,at);if(row.get("parent_revision")==null)deny();at=str(row,"parent_revision");}throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);}
    private Map<String,Object> operation(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String id,String name,String actor,String target,String manifest,String requestHash){var row=one(db.queryForList("SELECT * FROM operation_record WHERE tenant_id=? AND operation_id=? LIMIT 2 FOR UPDATE",q.tenantId(),id));for(var e:Map.of("operation_name",name,"subject_id",actor,"created_by",actor,"target_id",target,"schema_version","1.0.0","schema_manifest_sha256",manifest,"classification",q.classification(),"request_sha256",requestHash).entrySet())same(e.getValue(),str(row,e.getKey()));if(row.get("error_code")!=null)bad();return row;}
    private void audit(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String actor,String action,String requestId,String manifest,JsonNode expected,LocalDateTime time)throws Exception{var row=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND project_id=? AND action=? AND request_id=? AND trace_id=? AND subject_id=? AND created_by=? AND result='SUCCESS' AND reason_code IS NULL AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? LIMIT 2 FOR UPDATE",q.tenantId(),q.projectId(),action,requestId,requestId,actor,actor,manifest,q.classification()));same(expected,plans.read(str(row,"resource_ref")));notBefore(TaskRunActivityJournal.time(row,"created_at"),time);}
    private void notBefore(LocalDateTime actual,LocalDateTime earliest){var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));if(actual.isBefore(earliest)||actual.isAfter(now))bad();}
